import{_ as a,H as n,f as e,i as p}from"./chunks/framework.BH2BK_3i.js";const E=JSON.parse('{"title":"15-规则引擎：如何快速响应突发的爬虫需求？","description":"","frontmatter":{},"headers":[{"level":2,"title":"规则引擎：架构分析","slug":"规则引擎-架构分析","link":"#规则引擎-架构分析","children":[]},{"level":2,"title":"规则引擎：后端","slug":"规则引擎-后端","link":"#规则引擎-后端","children":[{"level":3,"title":"信息收集模块","slug":"信息收集模块","link":"#信息收集模块","children":[]},{"level":3,"title":"规则校验模块","slug":"规则校验模块","link":"#规则校验模块","children":[]},{"level":3,"title":"规则判定结果输出","slug":"规则判定结果输出","link":"#规则判定结果输出","children":[]}]},{"level":2,"title":"规则引擎：前端","slug":"规则引擎-前端","link":"#规则引擎-前端","children":[{"level":3,"title":"pre：信息收集。","slug":"pre-信息收集。","link":"#pre-信息收集。","children":[]},{"level":3,"title":"ing：信息处理","slug":"ing-信息处理","link":"#ing-信息处理","children":[]},{"level":3,"title":"post：前端处理","slug":"post-前端处理","link":"#post-前端处理","children":[]}]},{"level":2,"title":"小结","slug":"小结","link":"#小结","children":[]},{"level":2,"title":"思考题","slug":"思考题","link":"#思考题","children":[]}],"relativePath":"反爬虫兵法演绎20讲/15-规则引擎：如何快速响应突发的爬虫需求？.md","filePath":"反爬虫兵法演绎20讲/15-规则引擎：如何快速响应突发的爬虫需求？.md","lastUpdated":1795554197000}'),i={name:"反爬虫兵法演绎20讲/15-规则引擎：如何快速响应突发的爬虫需求？.md"};function l(t,s,h,o,r,c){return n(),e("div",null,[...s[0]||(s[0]=[p(`<h1 id="_15-规则引擎-如何快速响应突发的爬虫需求" tabindex="-1">15-规则引擎：如何快速响应突发的爬虫需求？ <a class="header-anchor" href="#_15-规则引擎-如何快速响应突发的爬虫需求" aria-label="Permalink to &quot;15-规则引擎：如何快速响应突发的爬虫需求？&quot;">​</a></h1><p>你好，我是 DS Hunter，反爬虫专家，又见面了。</p><p>我们前面很多地方都提到了规则引擎。这里再重申一下规则的定义：</p><ul><li>规则（rule）：使用任何技术手段，对线上请求特征按照指定的条件（condition）或方法（callback）进行检测验证，并执行指定操作的过程。在部分系统里，这个也被称为过滤器（filter）。</li></ul><p>如果说低耦合是为了保护你不死，那么规则引擎就是你的战斗利器，相当于将军的兵器，来鉴别爬虫。严格来说，整个反爬系统所有的操作，最终都是各种形态的规则引擎。</p><p>这里我们把规则引擎分为后端和前端两部分来讨论。为了使论述更佳清晰易懂，这里我们将BFF 的规则引擎认为是前端的部分。</p><p>此外，做好规则引擎之后，还是需要用上一章的低耦合的办法去接入的，你也可以根据上一讲的内容自行组合。</p><p>那么，我们就直接进入规则引擎的讲解，关注它本身的架构。</p><h2 id="规则引擎-架构分析" tabindex="-1">规则引擎：架构分析 <a class="header-anchor" href="#规则引擎-架构分析" aria-label="Permalink to &quot;规则引擎：架构分析&quot;">​</a></h2><p>从结构上来说，前后端是各有一套规则引擎的。其中，前端的和 BFF 紧密结合，我们可以放一起讨论。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%8F%8D%E7%88%AC%E8%99%AB%E5%85%B5%E6%B3%95%E6%BC%94%E7%BB%8E20%E8%AE%B2/images/15-%25E8%25A7%2584%25E5%2588%2599%25E5%25BC%2595%25E6%2593%258E/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%8F%8D%E7%88%AC%E8%99%AB%E5%85%B5%E6%B3%95%E6%BC%94%E7%BB%8E20%E8%AE%B2/images/15-%25E8%25A7%2584%25E5%2588%2599%25E5%25BC%2595%25E6%2593%258E/1.png" alt=""></a></p><p>你可以从图里看到，无论是前端还是后端，大致流程都是收集信息，配置规则，对应的模块进行处理，然后根据规则进行指定的操作。这个过程我们可以认为是数据驱动，也可以认为是规则驱动。当然，正是因为规则驱动，所以才有了规则引擎这样的名字。</p><p>在发现了前后端的相似性之后，你可能会有一个疑问：既然前后端都需要规则配置，那么这个是否可以抽象出一个配置模块，同时对前后端进行配置呢？</p><p>答案是可以的，但是要看你的业务权限到什么范围。理论上说，一个配置系统同时配置前后端，能减少配置压力。但是，如果对应的系统不在你权限范围内，就意味着你可以随意变更别人模块的权限，通常推行压力会大很多。而且这不是什么技术问题，而是一个办公室政治问题。不同的团队可能会有不同的难度。这个没有标准答案。</p><h2 id="规则引擎-后端" tabindex="-1">规则引擎：后端 <a class="header-anchor" href="#规则引擎-后端" aria-label="Permalink to &quot;规则引擎：后端&quot;">​</a></h2><p>实际上，很多公司都有做反爬虫的系统，但是它们看起来很高大上，实际效果却一般。原因就是他们只做了这个规则引擎，并没有深入下去。这样的现象，恰恰也说明了规则引擎的基础性以及重要性。</p><p>按照我们前面的介绍，后端通常是做请求校验的，也就是对 HTTP 请求进行规则校验。我们再来复习一下前一张的流程图：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%8F%8D%E7%88%AC%E8%99%AB%E5%85%B5%E6%B3%95%E6%BC%94%E7%BB%8E20%E8%AE%B2/images/15-%25E8%25A7%2584%25E5%2588%2599%25E5%25BC%2595%25E6%2593%258E/2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%8F%8D%E7%88%AC%E8%99%AB%E5%85%B5%E6%B3%95%E6%BC%94%E7%BB%8E20%E8%AE%B2/images/15-%25E8%25A7%2584%25E5%2588%2599%25E5%25BC%2595%25E6%2593%258E/2.png" alt=""></a></p><p>可以看到，规则引擎是独立于应用层而存在的。那也就意味着要么 SLB 调用规则引擎，要么反爬 SDK 调用规则引擎。这同时也意味着规则引擎的独立性极强，可以随时被熔断。</p><p>记住这个观点，然后我们逐个模块来看。</p><h3 id="信息收集模块" tabindex="-1">信息收集模块 <a class="header-anchor" href="#信息收集模块" aria-label="Permalink to &quot;信息收集模块&quot;">​</a></h3><p>第一个模块就是信息收集模块。</p><p>根据我们前一讲低耦合的说法，规则引擎是由反爬 SDK 来调用的，而不是耦合在系统内部。那么，规则引擎应该是个独立系统。这意味着，他不可能拿到请求的上下文，因此不可能直接分析 HTTP Header。而我们就需要把 HTTP Header 都带过去。</p><p>给另一个系统带参数过去，方法很简单，就是调用时序列化当前 HTTP Header，然后作为调用参数传给对方即可。这里传参本身没什么难度。不过，需要权衡的是，日志在哪里记录？是调用方，还是规则引擎？</p><p>原则上来说，我建议放在规则引擎。虽然放在调用方记录会更加稳妥、不丢日志，但是出于以下考虑，还是放规则引擎方比较合适：</p><ol><li>放在调用方， 会增加接入难度：</li></ol><p>日志如果集成在调用方，要么是给业务方一个接口，要么是集成在 SDK 里面。无论是哪一种情况，都增加了出错的可能性，并且出错了都难以调试——因为这是跨团队代码。</p><p>因此，出于简单考虑，应该尽可能减少 SDK 的调用成本。最好就一句话：结果 = 调用反爬()，然后代码结束。</p><ol start="2"><li>放在调用方，会增加对业务系统的耦合：</li></ol><p>上一讲详细解释了的低耦合的思维方式。</p><ol start="3"><li>放在调用方，会增加调用方的压力。</li></ol><p>因此，我们的规则引擎应该自带日志模块。</p><p>日志的问题讨论结束了，我们回到正题。后端规则引擎基本上就是收集 HTTP Header 了，而HTTP 协议本身是一个文本协议，因此 Header 本身也是文本，这也降低了我们序列化的成本。因此，暂时无需考虑序列化对系统造成的压力。但是，依然要对 HTTP Header 做限制，避免对方恶意攻击 header 的 count，消耗序列化成本，把反爬虫系统拖熔断。</p><p>规则引擎接收到请求参数，就可以对 Header 的内容进行规则判定了。这里因为还要做反序列化，而 HTTP 本身又有大量的 encode 和 decode 操作，因此一定要小心处理，不然很容易埋bug，类似忘记调用 encode、调用 decode 次数错误等等都有可能出现。而 encode 和decode 类型的 bug，一旦出现，都是概率型 bug，不是必现型 bug，调试会极难。同样的道理，log 记录也要注意这个问题。</p><h3 id="规则校验模块" tabindex="-1">规则校验模块 <a class="header-anchor" href="#规则校验模块" aria-label="Permalink to &quot;规则校验模块&quot;">​</a></h3><p>后端的规则校验模块本质上是一个策略模式。</p><p>策略模式简单来说就是对策略进行解耦。事实上，大部分设计模式都逃不掉“解耦”这个概念。而规则，也就是 Rule，本质上也可以认为是一个策略。因为根据指定的规则，我们可以进行判定，输出结果。这本身也算一种策略。</p><p>我们看这样的伪代码：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>interface IContext;</span></span>
<span class="line"><span>interface IRuleResult;</span></span>
<span class="line"><span>interface IRule{</span></span>
<span class="line"><span> IRuleResult Check(IContext context);</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>// 其中一个实现类</span></span>
<span class="line"><span>public HttpHeaderEncodingRule : IRule{</span></span>
<span class="line"><span> IRuleResult Check(IContext context){</span></span>
<span class="line"><span>   // 检测encoding是否正确</span></span>
<span class="line"><span>   return new ....</span></span>
<span class="line"><span> }</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>public HttpHeaderCookieRule:IRule{</span></span>
<span class="line"><span> IRuleResult Check(IContext context){</span></span>
<span class="line"><span>   // 检测cookie是否正确</span></span>
<span class="line"><span>   return new...</span></span>
<span class="line"><span> }</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>类似这样的规则还有很多。 如果单独判定一条，那就是策略模式。如果一起判定呢？你可能会忽然说：老师，不对，这就成了职责链模式了！你这模式好乱啊！</p><p>是的，但是你有没有想过，你创建这些 Rule 的时候，还要使用抽象工厂呢？实际上设计模式通常都是组合使用的，只要实现了高内聚低耦合，用了什么设计模式并不重要。</p><p>看，不但系统架构要低耦合，设计代码也是一样的！</p><h3 id="规则判定结果输出" tabindex="-1">规则判定结果输出 <a class="header-anchor" href="#规则判定结果输出" aria-label="Permalink to &quot;规则判定结果输出&quot;">​</a></h3><p>规则引擎判定完结果之后，是不是可以直接输出给前端，给出判定结果，然后给出对应的处理呢？</p><p>不是的。你直接给前端，告诉用户：你是爬虫，你完了，我这里肯定要搞你，我打算这么搞你。以下省略代码 3000 行……</p><p>你当爬虫傻么？他一看：什么，我被搞了，不行我去调试一下，兄弟们先不爬了。</p><p>所以，爬虫需要低调，难道反爬虫就不需要吗？</p><p>那么，我们的处理就应该是静默处理。也就是说，爬虫默默拿到处理后的数据就可以了，不要在前端进行任何的判定。只要有判定，那么就容易分析出反爬虫的结果。这是反爬虫的大忌。例如你要调整价格，那么直接把价格在后端（或者 BFF）拉高然后吐给前端即可。</p><p>如果你默默给了个提价比例给前端，让前端自己去提价……好吧，我只能说你们的前端也太好欺负了。</p><h2 id="规则引擎-前端" tabindex="-1">规则引擎：前端 <a class="header-anchor" href="#规则引擎-前端" aria-label="Permalink to &quot;规则引擎：前端&quot;">​</a></h2><p>前端部分主要是规则引擎的辅助。我们来看下具体的辅助打法。</p><h3 id="pre-信息收集。" tabindex="-1">pre：信息收集。 <a class="header-anchor" href="#pre-信息收集。" aria-label="Permalink to &quot;pre：信息收集。&quot;">​</a></h3><p>整个处理的最前置就是信息收集。我们前面讲过，一个主要的前端收集点就是 DOM 指纹。所以，我们把重点放在这里。</p><p>所谓的 DOM 指纹，我们也提过，实际上是 DOM 和 BOM 的混合。但是都是在 window 上拉取的（因为 document 也在 window 上，可以用 window.document 来访问），所以用 window做根节点拉取即可。你要是想叫 BOM 指纹也可以。</p><p>我们可以使用这样的字符串来描述定位符：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/navigator/geolocation/toString</span></span>
<span class="line"><span>代表执行window.navigator.geolocation.toString()</span></span>
<span class="line"><span>这个是早年phantomjs的一个重要监测点。</span></span>
<span class="line"><span>/document/body/div(3)/input[value]</span></span>
<span class="line"><span>代表获取body元素的第三个div里面的input元素，并取出value</span></span>
<span class="line"><span>这里顺便提一下这里的input是一个file类型的，你可以提前设置一个value进去。我们都知道，在浏览器安全</span></span></code></pre></div><p>这类代码可以写出很多。格式应该由你自己定义，上面只是 demo。但是要注意一点：你打算明文下发这段字符串吗？</p><p>当然不可能，这不是给爬虫送上门让他怀疑并分析吗。</p><p>我们应该下发的反而是加密结果，越复杂越好，甚至可以是一个树。js 调试的时候，因为有console.table 的存在，是不太怕长数据的，他怕的是多层级的数据。一个 js 实现的单链表，能直接绕晕调试工具；而一颗满二叉树，能大幅提升调试难度。那么，如果你的对象存在循环引用呢？console.table 会如何处理？你可以线下试试。</p><h3 id="ing-信息处理" tabindex="-1">ing：信息处理 <a class="header-anchor" href="#ing-信息处理" aria-label="Permalink to &quot;ing：信息处理&quot;">​</a></h3><p>信息处理部分主要是 BFF 的预处理。</p><p>我们前面提到过，BFF 可以做中转和聚合。这里就体现了聚合的一点。</p><p>首先，多个数据可以聚合成单个请求给后端，降低后端压力。其次，多个字段可以合并去重，降低报文的大小，减少后端的压力。最后，BFF 可以针对部分 Rule 直接进行处理，无需进入后端，这样也减少了低级爬虫对后端的冲击。</p><p>我们以 IP 拦截为例。</p><p>IP 拦截规则可以是固定 IP 拦截，可以是段拦截。这里的核心就是要降低复杂度。</p><p>我们都知道，如果根据规则一个一个去匹配，那么一定是可以检测完所有的 IP 的。但是这样做复杂度会大大提升。例如，你有 200 个 IP 段的规则，那么就要进行 200 次校验。这样随着规则的上升，复杂度就会不断提升。那么，如何让复杂度稳定在一个常数级别呢？</p><p>这里我们做一个简单的例子。例如，你的规则有以下几个：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># 固定IP黑名单</span></span>
<span class="line"><span>192.168.3.1</span></span>
<span class="line"><span>192.168.3.7</span></span>
<span class="line"><span># IP 段</span></span>
<span class="line"><span>192.168.4.*</span></span>
<span class="line"><span>192.168.5.*</span></span>
<span class="line"><span>192.168.8.*</span></span></code></pre></div><p>如果按照常规的做法，这里应该是，对固定 IP 进行一个循环，然后逐个判定。然后再对 IP 段进行 range 区间的判定，合在一起之后得出“是否落入 IP 黑名单”的结论。</p><p>你会发现，这里是五条规则，那么至少要判定 5 次。如果你有 n 个规则，那么就要判定 n次。也就是，随着规则的上升，判定速度会越来越慢。那么我们如何提升一下速度呢？</p><p>我们经过观察，就会发现，是不是开头不是 192.168 的，就根本不用判断了？我们肉眼一看就知道。那么根据前缀，直接就可以排除掉一堆啊。</p><p>这让你想起了什么数据结构呢？是的，这是一个前缀树。</p><p>我们把这几条规则汇总一下，就可以得到如下的样子：</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> &quot;192&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">   &quot;168&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">     &quot;3&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">       &quot;1&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">       &quot;7&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">     },</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">     &quot;4&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">     &quot;5&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">     &quot;8&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">   }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>在 BFF 里面，一旦你有了这棵树，那么一个 IP 进去，判定方式就很容易了。</p><p>这里我们还是举例来说明。现在，我们手里来了一个 IP：192.168.3.6</p><p>那么首先查找 192，结果为 true 吗？不为 true，是一个 object，那么用这个 object 继续找168，结果是 true 吗？不是 true，是一个 object。那么继续找，3，是 true 吗？不是 true，依然是 object。下一个是 6 了。object 取 6，是 true 吗？不是 true，是 undefined，等价于true。那么运行结果为 false，这个 IP 不在黑名单。</p><p>从头到尾，我们只进行了四次判定。而且，后续无论这个黑名单多大，我们的判定都是 4 次，也就是我们的算法复杂度是 O(4)，常数级别，那也就是 O(1)，因此极为可控。</p><p>当然，这只是个 demo。事实上，你还可以把 IP 转化为二进制，然后进行 32 次二叉树的查找，直接得出结果，也是没有问题的。甚至 IP 段是用子网掩码实现的，这个直接就与树的深度挂钩，思路和上面例子的思路都是一样的。</p><p>二进制的好处是，很多子网并不是工整的分割到 8 的倍数，因此可能会有一些很稀奇古怪的IP 段，例如 192.168.3.5/22 这类奇葩的数字。你可以自己展开下，看看这个树是不是忽然变得复杂了起来。但是二叉树就直接避免了这个问题。</p><p>这个例子的总体思路是什么呢？是我们要时刻记住，反爬就是要降低系统压力的，因此要时刻考虑效率问题，不能爬虫没拦到，把自己给累死了。</p><h3 id="post-前端处理" tabindex="-1">post：前端处理 <a class="header-anchor" href="#post-前端处理" aria-label="Permalink to &quot;post：前端处理&quot;">​</a></h3><p>前端处理相对就容易一些。实际上，大部分的作假，我们都是做在接口上了，也就是直接假装正经地给前端返回了正常但是不正确的数据。但是前端还是有一些小的动作可以做。</p><p>例如，如果你需要强制登录，那么可能接口返回就是一个未验证，不给数据的状态。这个时候就需要前端做一些兼容处理，例如跳转登录或者弹登录框，这类需要前端做兼容处理。当然，这个是前端基操了，只要能想得到，我相信你一定做得到。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><p>好了，这节课，我们着重研究了规则引擎的具体实现方式。实际上，线上的规则引擎会十分复杂。复杂并非难度大，复杂与难，一直是两件不同的事情。因此，我们这里的几个例子，只是给你提供了思路，后续可以按照这个思路自己去探索属于自己的规则引擎实现。</p><p>但是，你会发现，所有的反爬最终都逃不脱后端的信息收集，校验，以及规则判定输出。其中规则校验又牵扯到了低耦合的事情。同时，前端也根据时机，会进行信息收集，信息处理，以及前端兼容处理。其中，重点是降低消耗，不要在反爬的过程中消耗无谓的资源。这样，我们才能够更安全地进行操作。</p><p>要时刻记住：保住项目组，让项目组活下去，才有胜利的希望。如果无法存活，那么笑到最后的，就是你的对手。</p><h2 id="思考题" tabindex="-1">思考题 <a class="header-anchor" href="#思考题" aria-label="Permalink to &quot;思考题&quot;">​</a></h2><p>好了，又到了愉快的思考题时间。还是老规矩，三选一。</p><ol><li><p>32 层二叉树虽然在广度上变小了，但是层数变多了。它的效率真的会更高吗？会不会看起来很美好实际上并不如字符串的 IP 判定？你的判定依据是什么？</p></li><li><p>前端信息收集不能直接下发 xPath，避免被爬虫抓。那么你有什么办法来处理这个问题呢？</p></li><li><p>规则校验模块部分，我们说，可能同时使用策略模式，职责链，以及抽象工厂。那么你认为还可能有什么设计模式会混入其中呢？</p></li></ol><p>可以把想法写在评论区，让我看看你的奇思妙想。 反爬无定势，也许我也可以在评论区学习到更多的思路！</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%8F%8D%E7%88%AC%E8%99%AB%E5%85%B5%E6%B3%95%E6%BC%94%E7%BB%8E20%E8%AE%B2/images/15-%25E8%25A7%2584%25E5%2588%2599%25E5%25BC%2595%25E6%2593%258E/3.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%8F%8D%E7%88%AC%E8%99%AB%E5%85%B5%E6%B3%95%E6%BC%94%E7%BB%8E20%E8%AE%B2/images/15-%25E8%25A7%2584%25E5%2588%2599%25E5%25BC%2595%25E6%2593%258E/3.png" alt=""></a></p>`,93)])])}const u=a(i,[["render",l]]);export{E as __pageData,u as default};
